local _, ns = ...

-- Text captured in game that no other table covered, translated afterwards (build_capture_lua.py).
local exact = {
    ["(Complete)"] = "(Fuldfør)",
    ["(Dungeon)"] = "(Fangehul)",
    ["(PvP)"] = "(PvP)",
    ["(Raid)"] = "(Razzia)",
    ["<Click to Engrave Rune>"] = "<Klik for at gravere rune>",
    ["<The cat yawns and regards you through heavily-lidded eyes.>"] = "<Katten gaber og betragter dig med halvtunge øjne.>",
    ["All Runes"] = "Alle Runer",
    ["Alliance Towers Controlled"] = "Alliancens Tårne Kontrolleret",
    ["Available Channels"] = "Tilgængelige Kanaler",
    ["Blood Guard Pepmeddres"] = "Blodvagt Pepmeddres",
    ["Capture Crown Guard Tower, Eastwall Tower, Northpass Tower and Plaguewood Tower in the Eastern Plaguelands, then return to Emmisary Gormok at Light's Hope Chapel."] = "Erobr Kronvagtens Tårn, Østmur-tårnet, Nordpas-tårnet og Pestskov-tårnet i de Østlige Pestlande, og vend derefter tilbage til Udsending Gormok ved Lysets Håb-kapellet.",
    ["Click this button to clean up your bags.|n|nIt auto-sorts and moves items out of the way to make room for new items."] = "Klik på denne knap for at rydde op i dine tasker.|n|nDen sorterer automatisk og flytter genstande af vejen for at gøre plads til nye genstande.",
    ["Collapse options |A:editmode-up-arrow:16:11:0:3|a"] = "Sammenfold indstillinger |A:editmode-up-arrow:16:11:0:3|a",
    ["Damage:"] = "Skade:",
    ["Defense:"] = "Forsvar:",
    ["Deliver the Call to Arms Announcement to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands."] = "Lever Kald til Våben-kundgørelsen til Protokolvogteren ved Lysets Håb-kapellet i de Østlige Pestlande.",
    ["Enter Naxxramas and uncover the Fate of Ramaladni."] = "Skriv Naxxrammas ind og afdæk Ramaladdis Skæbne.",
    ["Filler Text"] = "Fyldtekst",
    ["Greetings, Pepmeddres. I am Duke Nicholas Zverenhoff of the Argent Dawn."] = "Hilsner, Pepmeddres. Jeg er Hertug Nikolaj Dyrehoff fra Sølvdæmringen.",
    ["Hej, druid. Undskyld mig, jeg har en samtale i gang med Rumlat. Han mener, at selv dette land ikke er uden for redning. "] = "Hej, druid. Undskyld mig, jeg har en samtale i gang med Rumlat. Han mener, at selv dette land ikke er uden for redning. ",
    ["Hello, Rayne. What brings the Cenarion Circle to the Plaguelands?"] = "Hej, Regn. Hvad fører Cenarion-kredsen til Pestlandene?",
    ["Hello, druid. Please excuse me as I am having a conversation with Rimblat. He believes that even this land is not beyond saving."] = "Hej, druide. Undskyld mig, jeg fører en samtale med Rumlat. Han mener, at selv dette land ikke er uden for redning.",
    ["Horde Territory"] = "Hordens Territorium",
    ["Horde Towers Controlled"] = "Hordens Tårne Kontrolleret",
    ["I would like to buy from you."] = "Jeg vil gerne købe hos dig.",
    ["I'm far too busy to be playing 'guess the smell' with you, tauren. State your business or get out of my sight!"] = "Jeg er alt for travl til at lege 'gæt lugten' med dig, tyrefolket. Sig, hvad du vil, eller forsvind mig af syne!",
    ["I'm what you call a capitalist, tauren."] = "Jeg er, hvad man kalder en kapitalist, tyrefolket.",
    ["Idol"] = "Idol",
    ["Invasion"] = "Invasion",
    ["Item Name"] = "Genstandsnavn",
    ["Level level race class"] = "Niveau niveau race klasse",
    ["Master craftsman Omarion just vanished one night. Like a toot in the wind... Poof! Gone! Bah, now I'm the only one left to craft the goods for the boys on the front lines. "] = "Mester-håndværker Omarjon forsvandt bare én nat. Som en prut i vinden... Puf! Væk! Bah, nu er jeg den eneste tilbage til at fremstille varerne til drengene på frontlinjen. ",
    ["Pepmeddres"] = "Pepmeddres",
    ["Power:"] = "Kraft:",
    ["PvP"] = "PvP",
    ["Pyntegenstand"] = "Pyntegenstand",
    ["Quest Title"] = "Questtitel",
    ["Rayne, where should I look for savage fronds?"] = "Regn, hvor skal jeg lede efter vilde bregnblade?",
    ["Services"] = "Tjenester",
    ["Show me your wares, Wilhelm."] = "Vis mig dine varer, Vilhelm.",
    ["The Argent Dawn placed the call for aid, and you, among others, have answered. There is no time for us to provide you with training. Our faith is placed in your abilities, and that you will join us in throwing back this Scourge threat."] = "Sølvdæmringen har sendt opfordringen om hjælp, og du er blandt dem, der har svaret. Der er ingen tid til at give dig træning. Vores tro er sat på dine evner, og at du vil slutte dig til os i at slå denne Svøben-trussel tilbage.",
    ["The Scourge have returned in greater numbers than we have seen before. The Argent Dawn is recruiting all willing and capable men and women to defend our lands.\n\nIf we share common cause, take this document to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands."] = "Svøben er vendt tilbage i større antal, end vi nogensinde har set. Sølvdæmringen hverver alle villige og dygtige mænd og kvinder til at forsvare vores lande.\n\nHvis vi deler en fælles sag, så tag dette dokument med til Protokolvogteren ved Lysets Håb-kapellet i Østlige Pestlande.",
    ["Vapenkjortel"] = "Våbenkjortel",
    ["Venture to Alterac Valley, located in the Alterac Mountains. Find and speak with Warmaster Laggrond - who stands outside the tunnel entrance - to begin your career as a soldier of Frostwolf. You will find Alterac Valley north of Tarren Mill at the base of the Alterac Mountains."] = "Begiv dig til Alterac-dalen, beliggende i Alterac-bjergene. Find og tal med Krigsmester Laggrønd - som står uden for tunnelindgangen - for at begynde din karriere som soldat i Frostulv. Du finder Alterac-dalen nord for Tarrenmølle ved foden af Alterac-bjergene.",
    ["Very well - your deeds have been entered into the records, and you are duly recognized for your efforts.  Keep up the good work, druid.\n\nIf you have any more signets to hand in, then I am able to assist you further in that regard."] = "Meget godt - dine bedrifter er blevet indført i protokollen, og du er behørigt anerkendt for din indsats.  Bliv ved med det gode arbejde, druide.\n\nHvis du har flere seglringe at aflevere, kan jeg hjælpe dig yderligere i den sag.",
    ["You earned this, scrub. Now, don't cry about your orders. Fill 'em or destroy 'em.\r\n"] = "Du fortjente det her, din lille nisse. Nu skal du ikke hyle over dine ordrer. Fyld dem ud eller ødelæg dem.\r\n",
    ["You know the drill, kid. One valor token gets you a craftsman's writ."] = "Du kender proceduren, unge. Ét modmærke giver dig Håndværkerens Brev.",
    ["You've come to join our order, have you not?"] = "Du er kommet for at slutte dig til vores orden, ikke sandt?",
    ["startrink"] = "stjernedrik",
    ["Ah! Wonderful. The wolf meat should do nicely. Oh, don't worry, Dinmor, I wouldn't forget my part of the bargain. Here, one of these should fit you."] = "Ah! Vidunderligt. Ulvekødet burde gøre det fint. Åh, bekymr dig ikke, Dinmor, jeg ville ikke glemme min del af handlen. Her, en af disse burde passe dig.",
    ["Ah, well aren't you a sturdy-looking one? Perhaps you can assist me with a thing or two. Not much help around here except for green apprentices, and they've other things to worry about."] = "Ah, nå, er du ikke en robust en at se på? Måske kan du assistere mig med et par ting. Der er ikke meget hjælp at hente her, undtagen grønne lærlinge, og de har andre ting at bekymre sig om.",
    ["Competing in the Battlegrounds!"] = "Deltagelse i Slagmarkerne!",
    ["Deliver the stack of letters to Talin Keeneye."] = "Lever bunken af breve til Talin Skarpøje.",
    ["Hm, I don't suppose you'd be willing to do a favor for me, lad? A stack of letters came through the pass today, but I don't have the time to send them along.\n\nThey're all addressed to Talin Keeneye. You can find him to the west down the road. He's set up camp next to the frozen lake.\n\nWhat do you say?"] = "Hm, du har vel ikke lyst til at gøre mig en tjeneste, knægt? En bunke breve kom gennem passet i dag, men jeg har ikke tid til at sende dem videre.\n\nDe er alle adresseret til Talin Skarpøje. Du finder ham mod vest, nede ad vejen. Han har slået lejr ved den frosne sø.\n\nHvad siger du?",
    ["Paladin"] = "Paladin",
    ["Read the Glyphic Memorandum and speak to Marryk Nurribit inside Anvilmar above Coldridge Valley."] = "Læs Glyfisk Memorandum og tal med Gifte Nurribit inde i Ambolmar oven for Kuldekam-dalen.",
    ["Tenacious little buggers, aren't they?"] = "Seje små krabater, ikke?",
    ["While you were helping me out, this memorandum was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the mage trainer Marryk. Take a gander at it and go find him inside Anvilmar when you've a chance."] = "Mens du hjalp mig, blev dette memorandum givet til mig, så jeg kunne videregive det til dig. Tag dig lidt tid til at læse det, når du får chancen. Jeg tror, det kom fra magiker-træneren Gifte. Kig på det og find ham inde i Ambolmar, når du har chancen.",
    ["Wolves giving you a bit of trouble? You'd do well to avoid the fangs and claws and other sharp bits, yes?"] = "Ulve giver dig lidt besvær? Du gør klogt i at undgå hugtænderne, klørne og de andre skarpe stykker, ja?",
    ["|TInterface\\DialogFrame\\UI-Dialog-Icon-AlertNew:16:16:0:0:64:64:0:64:0:64|t Dethrone|r"] = "|TInterface\\DialogFrame\\UI-Dialog-Icon-AlertNew:16:16:0:0:64:64:0:64:0:64|t Afsæt|r",
    ["  (PvP)"] = "  (SmS)",
    ["Apparently"] = "Tilsyneladende",
    ["If the problems we've had here are indicative of what is happening elsewhere in our lands, by Magni's beard, we have some troubles ahead of us! I can only hope that the king and Senate are taking steps to deal with the threat the troggs pose."] = "Hvis de problemer, vi har haft her, er et tegn på, hvad der sker andre steder i vores lande, så af Magnies skæg, har vi nogle problemer forude! Jeg kan kun håbe, at kongen og Senatet tager skridt til at tackle den trussel, trogerne udgør.",
    ["Ah good, now this will hit the spot.  Allow me to take a small break while I enjoy this scalding mornbrew!"] = "Ah godt, nu rammer det plet.  Lad mig tage en lille pause, mens jeg nyder denne Skoldhed Morgenbrygg!",
    ["Ahh, excellent. It's been a while since I received word from Ironforge."] = "Ahh, fremragende. Der er gået et stykke tid, siden jeg sidst fik bud fra Jernsmede.",
    ["Alliance Territory"] = "Alliancens Territorium",
    ["Aye, I'm Durnan Furcutter.  You have something for me?"] = "Jep, jeg er Durnan Pelsskærer.  Har du noget til mig?",
    ["Bring Felix's Box, Felix's Chest and Felix's Bucket of Bolts to Felix Whindlebolt in Anvilmar."] = "Bring Felix' Kasse, Felix' Bryst og Felix' Spand med Skruer til Felix Vindbolt i Ambolmar.",
    ["Deliver the letter to Grelin Whitebeard."] = "Lever brevet til Grelin Hvidskæg.",
    ["Excellent! I can go back to my... leisurely... hunting now. Thank you, Dinmor."] = "Fremragende! Nu kan jeg vende tilbage til min... afslappede... jagt. Tak, Dinmor.",
    ["Greetings, lad. I'm Grelin Whitebeard. I'm here to examine the threat posed by the growing numbers of trolls in Coldridge Valley. What have I found? It's a bit troubling..."] = "Hilsner, knægt. Jeg er Grelin Hvidskæg. Jeg er her for at undersøge truslen fra de voksende mængder af troll i Kuldekam-dalen. Hvad har jeg fundet? Det er lidt bekymrende...",
    ["Greetings, mage! Fine day for hunting, wouldn't you say? I've been having more than a little luck with boars, myself. Perhaps you'd like a shot?"] = "Hilsner, magiker! Fin dag til jagt, ville du ikke sige? Jeg har selv haft mere end lidt held med vildsvin. Måske vil du have et skud?",
    ["Greetings.  I'm a gnome mage trainer, and you're a mage."] = "Hilsner.  Jeg er en gnom-magikertræner, og du er en magiker.",
    ["Hello, mage!  Ready for some training?"] = "Hej, magiker!  Klar til noget træning?",
    ["I am interested in mage training."] = "Jeg er interesseret i magikertræning.",
    ["I sell the finest cloth and leather garb this side of the valley!"] = "Jeg sælger de fineste klæde- og læderdragter på denne side af dalen!",
    ["If I remember correctly, Grelin's camp is down the road to the southeast. No doubt he'll be eager to get his mail."] = "Hvis jeg husker rigtigt, ligger Grelins lejr nede ad vejen mod sydøst. Uden tvivl er han ivrig efter at få sin post.",
    ["Is there something I can help you with?"] = "Kan jeg være til hjælp med noget?",
    ["Now that hit the spot!  Nothing like a piping hot - nay, SCALDING mornbrew on a cold winter's day to warm your cackles of yer soul.\n\nHere ya go Dinmor - be a pal and take this empty mug back to Nori for me, would ya now."] = "Nu ramte det plet!  Intet slår en pibende varm - nej, SKOLDENDE morgenbryg på en kold vinterdag for at varme dine sjælekagler.\n\nVær så god, Dinmor - vær en ven og tag det tomme krus med tilbage til Nori for mig, vil du nu.",
    ["Oh, yeah! Arcane Arts... of course.\n\nHere's what you need to know, Dinmor: Don't get into too much trouble. Save some coin to buy me an ale... or any spells ya might want. And stay the heck away from Gnomeregan. Other than that, have a good day! I'll be here if you need me or want to train... or whatever."] = "Åh, jo! Arkan Kunst... selvfølgelig.\n\nHer er det, du skal vide, Dinmor: Undlad at komme i for meget ballade. Spar nogle mønter til at købe en øl til mig... eller enhver besværgelse, du måtte ønske dig. Og hold dig for pokker væk fra Gnomregan. Ellers: hav en god dag! Jeg er her, hvis du har brug for mig eller vil træne... eller hvad som helst.",
    ["Return Nori's Mug to Nori Pridedrift."] = "Returnér Noris Krus til Nori Stolthed.",
    ["Take a Scalding Mornbrew to Durnan Furcutter inside Anvilmar before it gets cold in five minutes!"] = "Tag en Skoldhed Morgenbrygg til Durnan Pelsskærer inde i Ambolmar, før den bliver kold om fem minutter!",
    ["Thank you, I've been waiting for these letters for quite some time...\n\nUnfortunately, these letters aren't all for me. This one is addressed to Grelin Whitebeard. He's not too far away if you'd like to deliver it to him."] = "Tak, jeg har ventet på disse breve i ganske lang tid...\n\nDesværre er brevene ikke alle til mig. Dette er adresseret til Grelin Hvidskæg. Han er ikke alt for langt væk, hvis du vil levere det til ham.",
    ["Yeah, what's that, gnome? Speak up, if you don't mind. I don't hear so good after a few ales."] = "Jo, hvad siger du, gnom? Tal højere, hvis du ikke har noget imod det. Jeg hører ikke så godt efter et par øl.",
    ["Yes? Do you have something for me?"] = "Ja? Har du noget til mig?",
    ["Upon periodic perusal of the nether, we came across the following reagents.  Good day, and... please be more careful when dealing with the arcane."] = "Ved periodisk gennemgang af tomrummet stødte vi på følgende reagenser.  God dag, og... vær venligst mere forsigtig når I omgås det arkane.",
    ["Argh! Those Light-blasted trolls!\n\n<He takes a few breaths and seems to settle down... a bit.>\n\nA group of them came in the night and stole my journal! I knew better than to trust that good-for-nothing appr..."] = "Av! De lysblæste trolde!\n\n<Han tager et par vejrtrækninger og virker til at falde lidt til ro... lidt.>\n\nEn flok af dem kom om natten og stjal min dagbog! Jeg burde have vidst bedre end at stole på den til-ingenting-duelige lærling...",
    ["Dungeon difficulty set to Normal"] = "Fangehulets sværhedsgrad sat til Normal",
    ["Escape the effects of any immobilization or movement speed reduction effect."] = "Undslip virkningerne af enhver immobilisering eller reduktion af bevægelseshastighed.",
    ["Excellent, Dinmor!  You'd be surprised how many couriers I meet who forget to do something as simple as bring back the mug.  Mugs don't grow on trees, or so they tell me!\n\nHere's a little something for the effort.  Thanks again for your help."] = "Fremragende, Dinmor! Du ville blive overrasket over hvor mange budbringere jeg møder, der glemmer at gøre noget så simpelt som at bringe krusen tilbage. Krus gror jo ikke på træer, siger de i hvert fald!\n\nHer er lidt for besværet. Tak igen for din hjælp.",
    ["Grelin Whitebeard wants you to kill Grik'nir the Cold, and retrieve his journal."] = "Grelin Hvidskæg vil have dig til at dræbe Grik'nir den Kolde og hente hans dagbog.",
    ["I trust the scalding mornbrew got to Durnan on time!  Did you remember to bring me back my mug?"] = "Jeg stoler på at den brændende morgenbryg nåede Durnan til tiden! Huskede du at tage min krus med tilbage?",
    ["My journal! They took it away to the cave. The one that had it... It was a big brute with some odd markings on his skin and face. I didn't get a much better look than that.\n\nYou've had some luck with the trolls, maybe you could go get it back for me?"] = "Min dagbog! De tog den med til hulen. Ham der havde den... Det var en stor brølende kæmpe med nogle underlige mærker på hud og ansigt. Jeg fik ikke et meget bedre kig end det.\n\nDu har haft lidt held med trolde, måske kunne du gå og hente den tilbage til mig?",
    ["Greetings.  I'm a mage trainer, and you're a mage."] = "Hilsner.  Jeg er en magiker-træner, og du er en magiker.",
    ["Quandary"] = "Dilemma",
    ["The Light protect you, mage."] = "Lyset beskytter dig, magiker.",
    ["All Subclasses"] = "Alle underklasser",
    ["Can I teach you how to turn the meat you find on beasts into a feast?"] = "Kan jeg lære dig at gøre det kød, du finder på bæsterne, om til et gilde?",
    ["Fill yer tankard and pull up a chair. We've stories to tell and kegs to empty."] = "Fyld din krus og træk en stol op. Vi har historier at fortælle og tønder at tømme.",
    ["Here, let me show you how to bind those wounds...."] = "Her, lad mig vise dig, hvordan du binder de sår....",
    ["I can teach you how to cook!"] = "Jeg kan lære dig at lave mad!",
    ["I can train you in First Aid techniques."] = "Jeg kan træne dig i førstehjælpsteknikker.",
    ["Train me."] = "Træn mig.",
    ["What can I do at an inn?"] = "Hvad kan jeg gøre på en kro?",
    ["Bring Samuel Fipps' Rester til Marlas Grav, og vend derefter tilbage til Novice Elret."] = "Bring Samuel Fipsens Rester til Marlas Grav, og vend derefter tilbage til Nybegynder Elret.",
    ["Hello, rogue!  Ready for some training?"] = "Hej, snigmorder!  Klar til lidt træning?",
    ["I would like to train."] = "Jeg vil gerne træne.",
    ["No other race on Azeroth has suffered as much as our people, rogue. To laugh in the face of death has become second nature for all of us."] = "Ingen andre race på Azerot har lidt så meget som vores folk, snigmorder. At le døden lige i øjnene er blevet sekundnatur for os alle.",
    ["SHIFT-T"] = "SKIFT-T",
    ["With the sanction of Lord Varimathras, the Deathstalkers' numbers grow. More blades to strike at our enemies when they least expect it."] = "Med Herre Varimatras' billigelse vokser Dødsstalkernes tal. Flere klinger, der kan give fjenderne stød, når de mindst venter det.",
    ["(Hold Shift)"] = "(Hold Skift)",
    ["Deliver the Sealed Letter to Glix Xizzix in the Undercity."] = "Aflever det Forseglet Brev til Glix Klikklak i Undergrunden.",
    ["Find Yvette Farthing, and deliver to her the letter from Thurman Agamand."] = "Find Ivette Fjerding, og aflever brevet fra Thurmann Agamand til hende.",
    ["Oi, what do you want?"] = "Hov, hvad vil du have?",
    ["Reagenser: |nSoul Shard"] = "Reagenser: |nSjælskår",
    ["Take Apothecary Johaan's findings to Apothecary Renferrel in Silverpine Forest."] = "Bring Apoteker Johans fund til Apoteker Renferrel i Sølvfyrreskoven.",
    ["Your bags are full."] = "Dine tasker er fulde.",
    ["Your class cannot use Bows"] = "Din klasse kan ikke bruge Buer",
    ["Your class cannot use Leather"] = "Din klasse kan ikke bruge Læder",
    ["Your class cannot use Mail"] = "Din klasse kan ikke bruge Ringbrynje",
    ["Your class cannot use One-Handed Maces"] = "Din klasse kan ikke bruge Enhånds-Køller",
    ["Your class cannot use Two-Handed Maces"] = "Din klasse kan ikke bruge Tohånds-Køller",
    ["Abandon \"The Family Crypt\"?"] = "Opgiv \"Familiekrypten\"?",
    ["Ah, one of our own. It is good to see our numbers are growing so rapidly that I can no longer keep track of the faces of our members.\n\nThat fool Thrall thinks I am working hard to cleanse the image of warlocks and prove we are his servants. Idiot! The Burning Legion will make ash of this entire world after it drains it completely."] = "Ah, en af vores egne. Det er godt at se, at vores tal vokser så hurtigt, at jeg ikke længere kan holde styr på medlemmernes ansigter.\n\nDen fjols Trael tror, jeg arbejder hårdt på at rense hekseriets image og bevise, at vi er hans tjenere. Idiot! Den Brændende Legion vil gøre hele denne verden til aske, når den har drænet den fuldstændigt.",
    ["Arcane:"] = "Arkan:",
    ["As the Dark Lady wills."] = "Som Den Mørke Dame ønsker.",
    ["Bring Migi's Lunch to him behind Grommash Hold."] = "Bring Mumles Frokost til ham bag Grommash-borgen.",
    ["Bring a Lieutenant's Insignia from the Burning Blade in Skull Rock to Thrall."] = "Bring en Løjtnantens Insignia fra Brændende Klinge i Kranieklippen til Trael.",
    ["Bring a Lieutenant's Insignia to Thrall in Orgrimmar."] = "Bring en Løjtnantens Insignia til Trael i Orgrimgrad.",
    ["Bring the Book of Ur from Shadowfang Keep to Keeper Bel'dugur."] = "Bring Bog om Ær fra Skyggehugger-fæstningen til Vogter Bel'dugur.",
    ["Bring the Nether Gem to Bethor Iceshard in the Undercity."] = "Bring Nether-ædelstenen til Bethor Isskår i Undergrunden.",
    ["Critical Strike:"] = "Kritisk Slag:",
    ["Deliver the Abominable Head to the Undercity."] = "Lever Afskyeligt Hoved til Undergrunden.",
    ["Find Deathstalker Adamant and Deathstalker Vincent inside Shadowfang Keep."] = "Find Dødsstalker Stålhård og Dødsstalker Vinsent inde i Skyggehugger-fæstningen.",
    ["Find Maur Grimtotem's corpse inside Ragefire Chasm and search it for anything of interest."] = "Find Maur Gribetotems lig inde i Vredesild-kløften og søg det for noget interessant.",
    ["Fire:"] = "Ild:",
    ["Frost:"] = "Frost:",
    ["Give Yelmak's Potion to Whuut."] = "Giv Yelmaks Eliksir til Vuut.",
    ["Greetings, traveler."] = "Hilsner, rejsende.",
    ["Hmm..."] = "Hmm...",
    ["I have the finest meats in Orgrimmar."] = "Jeg har de fineste bøffer i Orgrimgrad.",
    ["I thank you for the motivation."] = "Jeg takker dig for motivationen.",
    ["I wish to unlearn my class or legacy talents."] = "Jeg ønsker at glemme mine klasse- eller arvetalenter.",
    ["Main Hand:"] = "Hovedhånd:",
    ["Mana Regen:"] = "Mana-genopretning:",
    ["May I have another?"] = "Må jeg få en til?",
    ["Movement Speed:"] = "Bevægelseshastighed:",
    ["Now that the crystal is here..."] = "Nu hvor krystallen er her...",
    ["Place Clarice's Pendant on Yuriv's Tomb in Silverpine."] = "Placér Clarices Vedhæng på Yurivs Grav i Sølvfyr.",
    ["Put the spirit of Faldrim Anvilmar to rest."] = "Læg Faldrim Ambolmars ånd til hvile.",
    ["Ranged:"] = "Distance:",
    ["Return Gunther's Spellbook to him, on the island of Gunther's Retreat."] = "Returner Gunners Besværgelsesbog til ham, på øen Gunners Tilbagetog.",
    ["Slay Taragaman the Hungerer and recover Taragaman the Hungerer's Heart."] = "Dræb Taragaman den Sultne og gendan Taragaman den Sultnes Hjerte.",
    ["Speak with Magistrate Sevren in Brill."] = "Tal med Dommer Sevrin i Gryde-by.",
    ["Speak with Seereth Stonebreak in the Stonetalon Mountains."] = "Tal med Seereth Stenbrud i Stenklippe-bjergene.",
    ["Take the Grimtotem Satchel to Rahauro in Thunder Bluff."] = "Tag Grimtotem-tasken til Rahaurø i Tordenklippe.",
    ["There is no escape, even in death."] = "Der er ingen flugt, selv ikke i døden.",
    ["Visit Borstan's Firepit and tell him Thatog wants you to deliver Migi's lunch to him personally."] = "Besøg Brændstans Bålsted og fortæl ham, at Tykmave vil have dig til at levere Mumles frokost til ham personligt.",
    ["We SMASH IT WITH A HAMMER!"] = "VI SMADRER DEN MED EN HAMMER!",
    ["Wham!"] = "Bam!",
    ["Why should I pace myself if this is working?"] = "Hvorfor skulle jeg tage det roligt, hvis det her virker?",
    ["Yes!"] = "Ja!",
    ["Your class cannot use Guns"] = "Din klasse kan ikke bruge Geværer",
    ["and return to Kor'geld in Yelmak's Alchemy and Potions."] = "og vend tilbage til Kor'guld i Yelmaks Alkymi og Eliksirer.",
    ["deliver Migi's lunch to him personally."] = "lever Mumles frokost til ham personligt.",
    ["then bring his heart back to Neeru Fireblade in Orgrimmar."] = "så bring hans hjerte tilbage til Neeru Ildklinge i Orgrimgrad.",
    ["Access the control console at the Venture Company research site."] = "Få adgang til kontrolkonsollen på Ventureselskabets forskningssted.",
    ["Blizzard services are currently unavailable.|n|nYour Real ID and BattleTag friends will not show up. You will also not be able to send or receive new Real ID or BattleTag friend requests. A game restart may be required to re-enable functionality."] = "Snestorm-tjenester er midlertidigt utilgængelige.|n|nDine Ægte ID- og KampTag-venner vil ikke dukke op. Du vil heller ikke kunne sende eller modtage nye venneanmodninger via Ægte ID eller KampTag. Et spilgenstart kan være nødvendigt for at genaktivere funktionaliteten.",
    ["Bring the Secure Crate to Wharfmaster Dizzywig in Ratchet."] = "Bring Sikret Kasse til Havnemester Svimlig i Skralleby.",
    ["Brug: Teaches you how to craft Brawler's Leather Armor."] = "Brug: Lærer dig at fremstille Slagsbrors Læderrustning.",
    ["Brug: Teaches you how to craft Totemic Leather Armor."] = "Brug: Lærer dig at fremstille Totemist Læderrustning.",
    ["Collect the Highly Toxic Strain from Witherfang."] = "Saml den Yderst Giftige Stamme fra Visnetand.",
    ["Enchanting: Enchant Bracer - Minor Deflect"] = "Fortryllings: Fortrylling Armbeskytter - Mindre Afbøjning",
    ["Explore the waters of the Forgotten Pools"] = "Udforsk vandene i De Glemte Pøle",
    ["Find Mankrik's wife and then return to him in the Crossroads."] = "Find Mankriks kone og vend så tilbage til ham ved Korsvejen.",
    ["Hit Chance:"] = "Træffersikkerhed:",
    ["I came to the Crossroads from the south seeking help, warlock, but I find only cowards who turn their backs on me--even the mighty Thork insults me so. He is a good leader, but his dismissal of my plea causes me greater anger.\n\nHe claims my rage makes me hasty--that it clouds my judgement--but I will not rest until I have vengeance!"] = "Jeg kom til Korsvejen fra syd for at søge hjælp, hekser, men jeg finder kun kujoner, der vender ryggen til mig--selv den mægtige Tork fornærmer mig sådan. Han er en god leder, men hans afvisning af min anmodning gør min vrede endnu større.\n\nHan påstår, at mit raseri gør mig forhastet--at det tager dømmekraften fra mig--men jeg vil ikke hvile, før jeg har hævn!",
    ["I would like to talk about something else."] = "Jeg vil gerne tale om noget andet.",
    ["Investigate the disappearance of Edward Heartweaver in Ruins of Lordaeron."] = "Undersøg forsvinden af Edward Hjertevæver i Ruinerne af Herrelande.",
    ["Item level:"] = "Genstandsniveau:",
    ["Nature:"] = "Natur:",
    ["Pattern: Brawler's Leather Armor"] = "Mønster: Slagsbrors Læderrustning",
    ["Pattern: Totemic Leather Armor"] = "Mønster: Totemist Læderrustning",
    ["Reagenser: |nLesser Magic Essence"] = "Reagenser: |nMindre Magi-essens",
    ["Roll Need!"] = "Rul Behov!",
    ["Search Ragefire Chasm for Maur Grimtotem's corpse and search it for any items of interest."] = "Søg Vredesild-kløften efter Maur Gribetotems lig og undersøg det for eventuelle interessante genstande.",
    ["Shadow:"] = "Skygge:",
    ["Speak to Neeru Fireblade in Orgrimmar."] = "Tal med Neeru Ildklinge i Orgrimgrad.",
    ["Speak to Thrall in Orgrimmar and tell him what you've learned."] = "Tal med Trael i Orgrimgrad og fortæl ham, hvad du har lært.",
    ["Speak with Tonga Runetotem at the Crossroads."] = "Tal med Tonja Runetotem ved Korsvejen.",
    ["Spell Damage:"] = "Besværgelsesskade:",
    ["Spell Healing:"] = "Besværgelsesheling:",
    ["The enchanted flame resonates within you. Campfire effects gained while affected have increased duration."] = "Den fortryllede flamme genlyder i dig. Lejrbålseffekter opnået, mens du er påvirket, har øget varighed.",
    ["Turn in your sealed crates and the Shipping Label here"] = "Aflever dine forseglede kasser og Forsendelsesetiketten her",
    ["We've had trouble with shipments going missing across Azeroth. If you find any, I'd appreciate if you could return them to me."] = "Vi har haft problemer med forsendelser, der forsvinder rundt om i Azerot. Hvis du finder nogen, vil jeg sætte pris på, om du kunne returnere dem til mig.",
    ["Well met, warlock. You may speak to me unless you have direct business with my mistress Magatha.\n\nI deal with most of her tasks for her so she can concentrate on more important matters. Perhaps there are some things we could discuss before you seek audience with her?"] = "Velkommen, hekser. Du må gerne tale med mig, medmindre du har direkte ærinde hos min frue Magata.\n\nJeg klarer de fleste af hendes opgaver for hende, så hun kan koncentrere sig om vigtigere sager. Måske er der nogle ting, vi kunne drøfte, før du søger audiens hos hende?",
    ["What are Craftsman's Writs?"] = "Hvad er Håndværkerens Breve?",
    ["What are Waylaid Supply Crates?"] = "Hvad er Forsvundne Forsyningskasser?",
    ["Will you help me find my dog?"] = "Vil du hjælpe mig med at finde min hund?",
    ["Yes yes yes!  You're just the undead I'm looking for!\n\nSit!  We have much to discuss!!"] = "Ja ja ja!  Du er lige den udøde, jeg leder efter!\n\nSid!  Vi har meget at drøfte!!",
    ["<Othmar's head looks at you from nearby.>\r\n\r\nWhat... You... Want...\r\n\r\nFilthy... undead..."] = "<Oddmars hoved stirrer på dig fra nærliggende.>\r\n\r\nHvad... Du... Vil...\r\n\r\nSnavsede... udøde...",
    ["<The body looks incomplete and appears to be awaiting a head.>"] = "<Kroppen ser ufuldstændig ud og ser ud til at vente på et hoved.>",
    ["Bring the Crest of Lordaeron to Oran Snakewrithe in Undercity."] = "Bring Herrelandenes Våbenskjold til Orla Slangevrid i Undergrunden.",
    ["Deliver the Abominable Head to Master Apothecary Faranell within the Undercity."] = "Lever Afskyeligt Hoved til Mesterapoteker Faranell inden for Undergrunden.",
    ["Do not presume to speak to me as though you are my equal, warlock. Sylvanas is my queen, and I will do as she bids.\n\nIf you do not show the proper respect, I assure you, we can find a more than suitable place for you in the Nether.\n\nBut there is no reason we cannot have words if you wish to aid the Dark Lady..."] = "Anmaß dig ikke at tale til mig, som om du er min ligemand, hekser. Silvanas er min dronning, og jeg vil gøre, som hun befaler.\n\nHvis du ikke viser den rette respekt, kan jeg forsikre dig om, at vi kan finde et mere end passende sted til dig i Nether.\n\nMen der er ingen grund til, at vi ikke kan have en snak, hvis du ønsker at bistå Den Mørke Dame...",
    ["Investigate the disappearance of Edward Heartweaver in the Ruins of Lordaeron."] = "Undersøg forsvindingen af Edward Hjertevæver i Ruinerne af Herrelande.",
    ["Return to your corpse"] = "Retur til dit lig",
    ["The liquids and mixtures all bubble and spasm as you approach. Next to the equipment lies a large pair of tongs that look as though they would be adequate for dropping in samples of ooze.\n\nThere is safety gear present, but it appears to be dusty and well-ignored.\n\nYou don't think touching anything would be wise."] = "Væskerne og blandingerne bobler og krampetrækker, når du nærmer dig. Ved siden af udstyret ligger et stort par tang, som ser ud til at være passende til at dumpe prøver af slimvæsen i.\n\nDer er sikkerhedsudstyr til stede, men det ser ud til at være støvet og godt ignoreret.\n\nDu tror ikke, at det ville være klogt at røre ved noget.",
    ["This is not the first time I have had to reprimand you! The electrical pulses of this heart are much too strong. This new heart has seared almost all of the flesh and ligaments of this construct!"] = "Dette er ikke første gang, jeg har måttet irettesætte dig! Hjertets elektriske impulser er alt for stærke. Dette nye hjerte har brændt næsten alt kødet og alle ledbåndene i denne konstruktion!",
    ["UUUUUuuuuurrrgh!!"] = "ÅÅÅÅÅuuuuurrrgh!!",
    ["Vildtmenu |cffffd200(Escape)|r"] = "Spilmenu |cffffd200(Esc)|r",
}
